UPDATE content_revisions SET text=json_extract(?1,'$.text'),digest=json_extract(?1,'$.digest') WHERE content_id=json_extract(?1,'$.contentId') AND (owner_id=json_extract(?1,'$.automationId') OR content_id IN (SELECT content_id FROM automation_firings WHERE automation_id=json_extract(?1,'$.automationId')) OR owner_id IN (SELECT json_extract(definition_json,'$.value.definition.instructionId') FROM automations WHERE automation_id=json_extract(?1,'$.automationId')));
